class AsyncExactCalls(ABC):
    @abstractmethod
    async def exact(
        self,
        operation: Operation[P, R],
        params: P | None = None,
        *,
        query: Query | None = None,
        options: RequestOptions | None = None,
        strict: bool | None = None,
    ) -> R: ...

    @abstractmethod
    def exact_pages(
        self,
        operation: Operation[P, R],
        params: P | None = None,
        *,
        query: Query | None = None,
        options: RequestOptions | None = None,
        strict: bool | None = None,
        backwards: bool = False,
        max_pages: int | None = None,
    ) -> AsyncIterator[R]: ...

    @abstractmethod
    def exact_items(
        self,
        operation: Operation[P, R],
        params: P | None = None,
        *,
        query: Query | None = None,
        options: RequestOptions | None = None,
        strict: bool | None = None,
        backwards: bool = False,
        max_pages: int | None = None,
        limit: int | None = None,
    ) -> AsyncIterator[object]: ...

